import{_ as e}from"./chunks/11-settings.B_GZgwvL.js";import{_ as a,o as d,c as o,a0 as r}from"./chunks/framework.DVzt4Sxt.js";const T=JSON.parse('{"title":"Agent 配置与更新","description":"","frontmatter":{},"headers":[],"relativePath":"ops/agent.md","filePath":"ops/agent.md","lastUpdated":1791394961000}'),i={name:"ops/agent.md"};function s(n,t,c,l,h,_){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="agent-配置与更新" tabindex="-1">Agent 配置与更新 <a class="header-anchor" href="#agent-配置与更新" aria-label="Permalink to &quot;Agent 配置与更新&quot;">​</a></h1><p>Agent 装在每台要浏览的机器上，主动出站连 Hub。安装步骤见 <a href="/filebox/guide/install-agent">部署 Agent</a>。</p><h2 id="状态与配置" tabindex="-1">状态与配置 <a class="header-anchor" href="#状态与配置" aria-label="Permalink to &quot;状态与配置&quot;">​</a></h2><ul><li>配置文件：<code>agent.toml</code>（<code>--init-config</code> 创建，权限 0600）。</li><li>状态目录默认在系统 data dir 下的 <code>filebox</code>（可用 <code>FILEBOX_AGENT_DATA_DIR</code>）。</li><li>根目录、钉选、合集经 UI 下发并持久化；坏的更新不会毁掉上一份好配置。</li><li>断线后永久重连，身份不变、不产生重复侧栏条目。</li><li>多实例必须使用不同的 <code>FILEBOX_AGENT_DATA_DIR</code>。</li></ul><h2 id="环境变量摘要" tabindex="-1">环境变量摘要 <a class="header-anchor" href="#环境变量摘要" aria-label="Permalink to &quot;环境变量摘要&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>含义</th></tr></thead><tbody><tr><td><code>FILEBOX_AGENT_HUB</code></td><td>Hub URL（<code>https://</code> / <code>wss://</code>）</td></tr><tr><td><code>FILEBOX_AGENT_TOKEN</code></td><td>Agent token</td></tr><tr><td><code>FILEBOX_AGENT_NAME</code></td><td>侧栏显示名</td></tr><tr><td><code>FILEBOX_AGENT_DATA_DIR</code></td><td>状态目录</td></tr><tr><td><code>FILEBOX_ALLOW_INSECURE_HUB</code></td><td>允许明文 Hub（仅开发）</td></tr><tr><td><code>FILEBOX_AGENT_SOFFICE</code> / <code>_DIR</code></td><td>LibreOffice（可选）</td></tr><tr><td><code>FILEBOX_AGENT_TERMINAL_TOTP_SECRET</code></td><td>Terminal 2FA（可选）</td></tr><tr><td><code>FILEBOX_AGENT_STATS_TTL_SECS</code></td><td>sysinfo 缓存 TTL（默认 60）</td></tr><tr><td><code>FILEBOX_AGENT_DIR_CACHE_RESTAT_COOLDOWN_MS</code></td><td>目录缓存 re-stat 冷却</td></tr></tbody></table><p>Office 相关上限见 <a href="./office">Office 预览</a>。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><p>校验校验和后原地替换。建议与 Hub、前端大版本一起升。</p><h2 id="可选能力开关" tabindex="-1">可选能力开关 <a class="header-anchor" href="#可选能力开关" aria-label="Permalink to &quot;可选能力开关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>配置入口</th></tr></thead><tbody><tr><td>Office 预览</td><td><a href="./office">Office 预览</a></td></tr><tr><td>Terminal 2FA</td><td><code>./agent --setup-terminal-2fa</code> 或环境变量，见 <a href="/filebox/features/terminal">Terminal</a></td></tr><tr><td>Transfer</td><td>能力位 <code>temp_upload</code>；规则见 <a href="/filebox/features/transfer">Transfer</a></td></tr></tbody></table><p>在 UI <strong>Settings</strong> 可确认连接状态与已启用 roots：</p><p><img src="'+e+'" alt="Settings"></p>',14)])])}const b=a(i,[["render",s]]);export{T as __pageData,b as default};
